"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["34845"],{90409(e){e.exports=JSON.parse('{"id":"F361","slug":"policy-rate-pass-through","name":"Policy Rate Pass-Through to Banks and Borrowers","subject":"Banking & Financial Institutions","section":"Banking","topic":"How monetary policy reaches banks and borrowers","level":"Intermediate","aliases":["how monetary policy reaches banks and borrowers","deposit beta","loan beta","transmission mechanism"],"formula":{"latex":"\\\\Delta r_{loan}=\\\\beta_{L}\\\\,\\\\Delta r_{p},\\\\quad \\\\Delta NII=\\\\beta_{L}\\\\,A_{rs}\\\\,\\\\Delta r_{p}-\\\\beta_{D}\\\\,D_{rs}\\\\,\\\\Delta r_{p}","also":[],"text":"Change in loan rate = loan beta x change in policy rate; Change in deposit rate = deposit beta x change in policy rate; Change in bank net interest income = loan beta x rate-sensitive loans x change - deposit beta x rate-sensitive deposits x change; Extra annual interest for a floating borrower = loan rate change x balance"},"symbols":[{"symbol":"beta_L","meaning":"Loan beta: share of a policy rate change passed on to loan rates","unit":"number"},{"symbol":"beta_D","meaning":"Deposit beta: share passed on to deposit rates (often below the loan beta, so margins widen when rates rise)","unit":"number"},{"symbol":"A_rs, D_rs","meaning":"Floating-rate loans and rate-sensitive deposits","unit":"money"}],"when_to_use":"Use it to follow a central bank\'s rate move through to the people it affects. Banks pass higher rates to borrowers faster than to savers, so net interest income often rises when rates rise, unless depositors move money to better rates, which pushes the deposit beta up over time. Borrowers on floating loans feel the change at once, which is how policy slows spending.","worked_example":{"problem":"The policy rate rises 1 point. Loan beta is 0.6 and deposit beta 0.3. The bank has 3,000 of floating loans and 5,000 of rate-sensitive deposits. A borrower has a 300,000 floating loan.","inputs":{"dp":1,"bl":0.6,"bd":0.3,"a":3000,"d":5000,"bal":300000},"steps":[{"label":"Change in loan rate","working":"0.6 x 0.01","value":"0.60%"},{"label":"Change in deposit rate","working":"0.3 x 0.01","value":"0.30%"},{"label":"Extra interest earned on loans","working":"3000 x 0.006","value":"18.00"},{"label":"Extra interest paid on deposits","working":"5000 x 0.003","value":"15.00"},{"label":"Change in net interest income","working":"18-15","value":"3.00"},{"label":"Extra yearly interest for the borrower","working":"300000 x 0.006","value":"1,800.00"},{"label":"Extra per month","working":"1800 / 12","value":"150.00"}],"answer":"Loan rates rise 0.60% and deposit rates 0.30%. The bank earns 18.00 more on loans and pays 15.00 more on deposits, so net interest income changes by 3.00. The floating borrower pays 1,800.00 more a year, or 150.00 a month."},"calculator":{"available":true,"inputs":[{"id":"dp","label":"Change in policy rate","unit":"%","type":"number","default":1,"hint":""},{"id":"bl","label":"Loan beta","unit":"","type":"number","default":0.6,"hint":""},{"id":"bd","label":"Deposit beta","unit":"","type":"number","default":0.3,"hint":""},{"id":"a","label":"Rate-sensitive loans","unit":"money","type":"number","default":3000,"hint":""},{"id":"d","label":"Rate-sensitive deposits","unit":"money","type":"number","default":5000,"hint":""},{"id":"bal","label":"Floating-rate borrower balance","unit":"money","type":"number","default":300000,"hint":""}],"checks":[{"expr":"bl>=0 and bd>=0","message":"The betas cannot be negative."}],"steps":[{"id":"drl","label":"Change in loan rate","expr":"bl*dp","format":"pct2"},{"id":"drd","label":"Change in deposit rate","expr":"bd*dp","format":"pct2"},{"id":"ia","label":"Extra interest earned on loans","expr":"a*drl","format":"money"},{"id":"ed","label":"Extra interest paid on deposits","expr":"d*drd","format":"money"},{"id":"dnii","label":"Change in net interest income","expr":"ia-ed","format":"money"},{"id":"extra","label":"Extra yearly interest for the borrower","expr":"bal*drl","format":"money"},{"id":"mo","label":"Extra per month","expr":"extra/12","format":"money"}],"results":["drl","drd","dnii","extra"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"drl":0.006,"drd":0.003,"ia":18,"ed":15,"dnii":3,"extra":1800,"mo":150}},"finder":{"finds":"How a policy move changes bank income and borrower costs","needs":"Rate change, betas, floating balances"},"related":[{"slug":"repricing-gap","name":"Repricing Gap and Net Interest Income"},{"slug":"taylor-rule","name":"Taylor Rule"},{"slug":"money-multiplier","name":"Money Multiplier and Deposit Expansion"}],"related_ids":["F358","F088","F355"],"group":"Money, banks and the economy","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi mathvariant=\\"normal\\">\u0394</mi><msub><mi>r</mi><mrow><mi>l</mi><mi>o</mi><mi>a</mi><mi>n</mi></mrow></msub><mo>=</mo><msub><mi>\u03B2</mi><mi>L</mi></msub><mtext>\u2009</mtext><mi mathvariant=\\"normal\\">\u0394</mi><msub><mi>r</mi><mi>p</mi></msub><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi mathvariant=\\"normal\\">\u0394</mi><mi>N</mi><mi>I</mi><mi>I</mi><mo>=</mo><msub><mi>\u03B2</mi><mi>L</mi></msub><mtext>\u2009</mtext><msub><mi>A</mi><mrow><mi>r</mi><mi>s</mi></mrow></msub><mtext>\u2009</mtext><mi mathvariant=\\"normal\\">\u0394</mi><msub><mi>r</mi><mi>p</mi></msub><mo>\u2212</mo><msub><mi>\u03B2</mi><mi>D</mi></msub><mtext>\u2009</mtext><msub><mi>D</mi><mrow><mi>r</mi><mi>s</mi></mrow></msub><mtext>\u2009</mtext><mi mathvariant=\\"normal\\">\u0394</mi><msub><mi>r</mi><mi>p</mi></msub></mrow><annotation encoding=\\"application/x-tex\\">\\\\Delta r_{loan}=\\\\beta_{L}\\\\,\\\\Delta r_{p},\\\\quad \\\\Delta NII=\\\\beta_{L}\\\\,A_{rs}\\\\,\\\\Delta r_{p}-\\\\beta_{D}\\\\,D_{rs}\\\\,\\\\Delta r_{p}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"pmi-surprise","name":"PMI Diffusion Index and Data Surprise"},"next":{"slug":"portfolio-esg-score","name":"Portfolio ESG Score and Tilt vs Benchmark"},"lesson":null,"total":522}')}}]);